#!/usr/bin/env python3
# THE DEUTERONOMY WALK 11b — THE DOCKET, ONE RUN (2026-09-21): the docket's five instruments DERIVED from 10b's forms by asserted substitutions (10b derived them
# from 9b's the same way): ch13_docket_common.py, ch13_docket_rows.py, ch13_docket_uncred.py, ch13_credit_survey.py, ch13_credit_carry.py. Departures from 10b's
# forms, each asserted: the cells' names (cold_run_seducers.py's six, the design's F1-F6); the chunk cap 76,000 -> 64,000 bytes (10b's D2 lesson: a 76k chunk took
# two Read pages — one chunk one Read); NO run boundary (SPLIT_AT empty — the docket is ONE RUN by the ~700 clause). Run from the repo root.
import subprocess, os, re
ROOT = subprocess.check_output(['git', 'rev-parse', '--show-toplevel'], text=True).strip()
SP = os.path.dirname(os.path.abspath(__file__)); FORMS = f'{ROOT}/World/step9/forms_deuteronomy_walk'
def load(name):
    for d in (FORMS, SP):
        p = f'{d}/{name}'
        if os.path.exists(p): return open(p, encoding='utf-8').read()
    raise FileNotFoundError(name)
def sub(text, old, new, n=1):
    assert text.count(old) == n, (old[:60], text.count(old), n); return text.replace(old, new)
CELLS_OLD = "cold_run_place_name.py (F1 the_header_and_the_demolition, F2 the_place_chosen, F3 the_burnt_offerings_only_there, F4 the_profane_slaughter_the_blood_and_the_gates,\n# F5 the_border_enlarged_and_the_altar, F6 the_nations_cut_off_and_the_abomination — the design's six cells on the six claims' spans; the_readback the table)"
CELLS_NEW = "cold_run_seducers.py (F1 the_header, F2 the_prophet_and_the_test, F3 the_inciter, F4 the_city_heard_of_the_inquiry_and_the_sword,\n# F5 the_whole_offering_the_heap_and_the_mercy, F6 the_footer — the design's six cells on the six claims' spans; the_readback the table)"
# 1 common
t = load('ch12_docket_common.py')
t = sub(t, "# THE DEUTERONOMY WALK 10b (9b's form by derive_ch12_docket_tools.py)", "# THE DEUTERONOMY WALK 11b (10b's form by derive_ch13_docket_tools.py)")
t = sub(t, CELLS_OLD, CELLS_NEW)
t = sub(t, "# 10b: the credited rows carried with their ledgers (ch12_credit_carry.py — 9b's form)", "# 11b: the credited rows carried with their ledgers (ch13_credit_carry.py — 10b's form)")
t = t.replace('ch12', 'ch13'); assert 'ch12' not in t and '10b' not in t.replace("10b's form", ''), [l for l in t.split('\n') if 'ch12' in l or '10b' in l]
open(f'{SP}/ch13_docket_common.py', 'w', encoding='utf-8').write(t)
# 2 rows
t = load('ch12_docket_rows.py'); t = t.replace('ch12', 'ch13'); assert t.count('ch13') == 1; open(f'{SP}/ch13_docket_rows.py', 'w', encoding='utf-8').write(t)
# 3 uncred (the cap lowered; no boundary)
t = load('ch12_docket_uncred.py')
t = sub(t, "# 10b docket (9b's form) — the UNCREDITED rows of the dump printed WHOLE (THE WHOLE-ROW RULE) into chunk files of at most 76,000 bytes each (one chunk one Read —\n# the cost rules' rule C; 9b's cap was 27,000 for the shell's print), in dump order; the chunk",
           "# 11b docket (10b's form) — the UNCREDITED rows of the dump printed WHOLE (THE WHOLE-ROW RULE) into chunk files of at most 64,000 bytes each (one chunk one Read —\n# the cost rules' rule C; 10b's cap was 76,000 and its chunks took two pages), in dump order; the chunk")
t = sub(t, "CAP = 76000\nSPLIT_AT = {582, 933}   # the docket runs' boundaries (D1 the rows before Avodah Zarah 45a:1; D2a Avodah Zarah and Chullin's five stretches before Bekhorot 15a:1 — the room left under the 600k cap after D1 took D2's first half; D2b the rest) — the dump's own order, the indexes computed at the derive: a chunk never spans two docket runs",
           "CAP = 64000\nSPLIT_AT = set()   # ONE docket run this chapter (566 addresses, 196 credited — under the ~700 clause): no run boundary")
t = t.replace('ch12', 'ch13'); assert 'ch12' not in t; open(f'{SP}/ch13_docket_uncred.py', 'w', encoding='utf-8').write(t)
# 4 survey
t = load('ch12_credit_survey.py'); t = sub(t, "# 10b docket (9b's form) — the credited addresses by ledger", "# 11b docket (10b's form) — the credited addresses by ledger")
t = t.replace('ch12', 'ch13'); assert 'ch12' not in t; open(f'{SP}/ch13_credit_survey.py', 'w', encoding='utf-8').write(t)
# 5 carry
t = load('ch12_credit_carry.py')
t = sub(t, "# 10b docket (9b's form) — THE CREDITED ROWS CARRIED WITH THEIR LEDGERS (THE WHOLE-ROW RULE", "# 11b docket (10b's form) — THE CREDITED ROWS CARRIED WITH THEIR LEDGERS (THE WHOLE-ROW RULE")
t = sub(t, "# ch12_credited_rows.py (CREDITED_SPEC in dump order) and ch12_uncred_unres.txt (the unresolved rows whole — 9b's _09 name would collide with a chunk this chapter); prints the counts.",
           "# ch13_credited_rows.py (CREDITED_SPEC in dump order) and ch13_uncred_unres.txt (the unresolved rows whole); prints the counts.")
t = sub(t, "out = ['# 10b docket — THE CREDITED ROWS CARRIED WITH THEIR LEDGERS, generated by ch12_credit_carry.py (9b\\'s form; never typed)",
           "out = ['# 11b docket — THE CREDITED ROWS CARRIED WITH THEIR LEDGERS, generated by ch13_credit_carry.py (10b\\'s form; never typed)")
t = t.replace('ch12', 'ch13'); assert 'ch12' not in t and '9b' not in t; open(f'{SP}/ch13_credit_carry.py', 'w', encoding='utf-8').write(t)
for f in ('ch13_docket_common.py', 'ch13_docket_rows.py', 'ch13_docket_uncred.py', 'ch13_credit_survey.py', 'ch13_credit_carry.py'):
    print('written', f, os.path.getsize(f'{SP}/{f}'), 'bytes')
